const CheckpointJobAccepted = "job_accepted"

// CheckpointJobAssigned is the "job_assigned" checkpoint: The server assigned the job.
const CheckpointJobAssigned = "job_assigned"

// CheckpointJobReceived is the "job_received" checkpoint: The worker received the job request.
const CheckpointJobReceived = "job_received"

